module multi_pipe_8bit(
    input clk, 
    input rst_n, 
    input mul_en_in, 
    input [7:0] mul_a, 
    input [7:0] mul_b, 
    output mul_en_out, 
    output [15:0] mul_out
);
// Define parameters for states
parameter IDLE = 3'b000;
parameter LOAD = 3'b001;
parameter CALC = 3'b010;
parameter OUT = 3'b011;
// Define registers for storing input values
reg [2:0] mul_en_out_reg;
reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
// Define registers for storing partial products
reg [15:0] temp [0:7];
// Define registers for storing partial sums
reg [15:0] sum [0:3];
// Define register for storing final product
reg [15:0] mul_out_reg;
// Sequential logic for input control
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 3'b0;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
    end
end
// Sequential logic for input registers
always @(posedge clk) begin
    if (mul_en_in) begin
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
    end else begin
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
    end
end
// Combinational logic for generating partial products
genvar i;
generate
    for(i = 0; i < 8; i=i+1) begin
        always @* begin
            case(mul_b_reg[i])
                1'b0 : temp[i] = 16'b0;
                1'b1 : temp[i] = {{(8-i){1'b0}}, mul_a_reg, {(i){1'b0}}};
            endcase
        end
    end
endgenerate
// Sequential logic for calculating partial sums
always @(posedge clk) begin
    sum[0] <= temp[0] + temp[1];
    sum[1] <= temp[2] + temp[3];
    sum[2] <= temp[4] + temp[5];
    sum[3] <= temp[6] + temp[7];
end
// Sequential logic for calculating final product
always @(posedge clk) begin
    mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
end
// Assign output signals
assign mul_en_out = mul_en_out_reg[2];
assign mul_out = mul_en_out_reg[2] ? mul_out_reg : 16'b0;
endmodule
